args.cmd:
cd /workspace && rm -f spec/models/user_spec.rb && (bin/rails server -p 3000 -e test > /tmp/server.log 2>&1 &) && sleep 8 && echo "--- signup ---" && curl -s -o /dev/null -w "%{http_code}
" http://localhost:3000/signup && echo "--- protected (no auth) ---" && curl -s -o /dev/null -w "%{http_code} -> %{redirect_url}
" http://localhost:3000/protected && echo "--- login page ---" && curl -s -o /dev/null -w "%{http_code}
" http://localhost:3000/login

